window.D1_EXPERIENCES={
VISION:{scene:"vision",subtitle:"What God reveals becomes the mark toward which you move.",scripture:{text:"Where there is no vision, the people perish: but he that keepeth the law, happy is he.",ref:"Proverbs 29:18 KJV",thought:"The Word governs the vision. Biblical vision is not imagination without restraint; it is sight disciplined by what God has spoken."},see:{lead:"Vision sees beyond present conditions to God-given possibility.",overline:"LOOK BEYOND WHAT IS",title:"SEE WHAT CAN BE",body:"See the destination clearly enough that present resistance cannot redefine it."},mindset:{lead:"I will not allow present circumstances to become the boundary of my expectation.",body:"I align my thinking with the Word and view the circumstance from the promise rather than measuring the promise by the circumstance."},declaration:["I SEE THE MARK.","I RECEIVE GOD'S WORD.","I MOVE WITH PURPOSE.","I WILL NOT CAST OFF RESTRAINT.","I HAVE DOMINION."],doit:{lead:"Revelation demands movement.",body:"Write the vision you see and identify one faithful action you can take now."}},
FAITH:{scene:"faith",subtitle:"Faith receives God's Word as the governing reality before sight changes.",scripture:{text:"So then faith cometh by hearing, and hearing by the word of God.",ref:"Romans 10:17 KJV",thought:"Faith is not manufactured optimism. Its source is hearing what God has said."},see:{lead:"See the promise before you see the evidence.",overline:"HEAR THE WORD",title:"SEE BY FAITH",body:"Let the Word form the picture by which you interpret what is presently visible."},mindset:{lead:"My expectation is trained by God's Word, not by fear.",body:"I refuse to make temporary evidence greater than the truth God has spoken."},declaration:["I HEAR THE WORD.","I BELIEVE GOD.","I WALK BY FAITH.","I WILL NOT BE GOVERNED BY FEAR.","I HAVE DOMINION."],doit:{lead:"Faith acts on what it believes.",body:"Identify the Word you are standing on and take one action consistent with it today."}},
DOMINION:{scene:"dominion",subtitle:"Created in God's image, mankind was commissioned to exercise delegated dominion.",scripture:{text:"And God said, Let us make man in our image, after our likeness: and let them have dominion...",ref:"Genesis 1:26 KJV",thought:"Dominion begins with identity and commission. Authority is received from God; it is not self-created."},see:{lead:"See yourself from the Creator's declaration.",overline:"IMAGE • LIKENESS",title:"LET THEM HAVE DOMINION",body:"The mandate begins with who God made mankind to be and what He assigned mankind to do."},mindset:{lead:"I think from divine identity, not from inferiority.",body:"I submit my authority to God and refuse both passivity and self-exaltation."},declaration:["I AM MADE IN GOD'S IMAGE.","I RECEIVE HIS MANDATE.","I EXERCISE STEWARDSHIP UNDER HIS AUTHORITY.","I WILL NOT LIVE PASSIVELY.","I HAVE DOMINION."],doit:{lead:"Dominion requires responsible stewardship.",body:"Name one area entrusted to you and take the next responsible action in it."}}
};